import React, { useState, useEffect } from 'react';
import axios from 'axios';
import { format } from 'date-fns';
import '../styles/workspacePage.css'

import NavMenu from "./SharedComponents/navMenu";
import CustomFooter from './SharedComponents/customFooter';

const ViewWorkspaces = () => {
  const [date, setDate] = useState(format(new Date(), 'yyyy-MM-dd'));
  const [workspaces, setWorkspaces] = useState([]);

  useEffect(() => {
    const fetchAvailableWorkspaces = async () => {
      try {
        const response = await axios.get(`/api/workspaces/available?date=${date}`);
        setWorkspaces(response.data);
      } catch (error) {
        console.error('Failed to fetch workspaces:', error);
      }
    };
    
    fetchAvailableWorkspaces();
  }, [date]);

  const handleDateChange = (event) => {
    setDate(event.target.value);
  };

  return (
    <div className="workspace-page">
      <NavMenu />
      <div className="workspace-container">
        <h1>Available Workspaces</h1>
        <input type="date" value={date} onChange={handleDateChange} />
        <ul>
          {workspaces.map(workspace => (
            <li key={workspace._id}>
              {workspace.name} - {workspace.location} - Status: {workspace.status}
            </li>
          ))}
        </ul>
      </div>
      <CustomFooter />
    </div>
  );
};

export default ViewWorkspaces;
